  const api = await import(new URL('variants/' + variant + '/lib/index.js', root));
  for (const stage of ['download', 'processAfterDownload', 'saveToDisk']) {
    const controller = new AbortController(), events = [];
    const options = api.options.defaultDownloadOptions(api.lifeCycle.defaultLifeCycle());
    options[stage] = [
      res => {
        events.push('first');
        queueMicrotask(() => { events.push('cancel'); controller.abort(new Error('cancelled between hooks')); });
        return res;
      },
      res => { events.push('second'); return res; }
    ];
    const pipeline = new api.downloader.PipelineExecutorImpl(options, options.req, options, controller.signal);
    const res = {...api.resource.createResource({type: 1, depth: 0, url: 'https://example.test/a',
